insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Más sobre Bolton$vn$), $vn$WHYES-001$vn$, $vn$Values$vn$, $vn$La realidad es que hay muchas compañías que dicen que sacan a la gente de deudas. Quiero compartir contigo lo que hace que Bolton Services Group sea una compañía realmente especial. Primero, es una organización basada en valores. Lo que esto significa es que ponen a las personas antes que las ganancias. Sus valores incluyen Apoyo y Responsabilidad. Estos son pilares de su compromiso de convertir a su comunidad en expertos financieros mediante educación que empodera, beneficios prácticos y protección al consumidor. Y eso es para que nunca vuelvas a estar en esta situación. Eso es importante para ti, ¿verdad?$vn$, array[$vn$CALM$vn$]::text[], $vn$[{"tone": "CALM", "text": "La realidad es que hay muchas compañías que dicen que sacan a la gente de deudas. Quiero compartir contigo lo que hace que Bolton Services Group sea una compañía realmente especial. Primero, es una organización basada en valores. Lo que esto significa es que ponen a las personas antes que las ganancias. Sus valores incluyen Apoyo y Responsabilidad. Estos son pilares de su compromiso de convertir a su comunidad en expertos financieros mediante educación que empodera, beneficios prácticos y protección al consumidor. Y eso es para que nunca vuelvas a estar en esta situación. Eso es importante para ti, ¿verdad?"}]$vn$::jsonb, null, null, null, 10, $vn$Drop your energy here, do not raise it. This lands as conviction, not enthusiasm. Sound like you are telling them something you actually believe.$vn$, $vn$These are not the same as the others who called me.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Más sobre Bolton$vn$), $vn$WHYES-002$vn$, $vn$What You Get$vn$, $vn$Además de salir de deudas, recibes educación de un coach financiero certificado, más de 10,000 descuentos en casi cualquier cosa que puedas imaginar, el pago de tu programa se reporta como una línea de crédito para estabilizar tu puntaje, un portal personalizado para que puedas seguir cada paso del proceso desde la palma de tu mano, un abogado disponible para cualquier pregunta o problema legal, y una gran cantidad de educación pasiva sobre dinero, crédito y cómo manejar dificultades financieras.$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Además de salir de deudas, recibes educación de un coach financiero certificado, más de 10,000 descuentos en casi cualquier cosa que puedas imaginar, el pago de tu programa se reporta como una línea de crédito para estabilizar tu puntaje, un portal personalizado para que puedas seguir cada paso del proceso desde la palma de tu mano, un abogado disponible para cualquier pregunta o problema legal, y una gran cantidad de educación pasiva sobre dinero, crédito y cómo manejar dificultades financieras."}]$vn$::jsonb, null, null, null, 20, $vn$A list this long dies if it is read flat. Vary your pace, breathe between items, and let a couple of them land harder than the rest.$vn$, $vn$This is far more than I thought I was buying.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Más sobre Bolton$vn$), $vn$WHYES-003$vn$, $vn$Career Platform$vn$, $vn$Casi se me olvida, también tienes acceso gratis a una plataforma de vanguardia para desarrollo profesional y recursos. Esto te da acceso a un coach de carrera, capacitación de habilidades, certificaciones y, por supuesto, una plataforma de empleos que recomienda trabajos en tu área para los que estás calificado, de todas las plataformas de empleo de Estados Unidos. Todo esto está incluido sin costo adicional, y es a través de Slate..., has escuchado de ellos, ¿verdad?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Casi se me olvida, también tienes acceso gratis a una plataforma de vanguardia para desarrollo profesional y recursos. Esto te da acceso a un coach de carrera, capacitación de habilidades, certificaciones y, por supuesto, una plataforma de empleos que recomienda trabajos en tu área para los que estás calificado, de todas las plataformas de empleo de Estados Unidos. Todo esto está incluido sin costo adicional, y es a través de Slate..., has escuchado de ellos, ¿verdad?"}]$vn$::jsonb, null, null, null, 30, $vn$"I almost forgot" should sound genuinely spontaneous. Real pause before the Slate question, then let them answer before you respond.$vn$, $vn$They just handed me something extra I did not ask for.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Más sobre Bolton$vn$), $vn$WHYES-003A$vn$, $vn$Slate — if yes$vn$, $vn$¡Claro que sí!$vn$, array[]::text[], $vn$[{"tone": "", "text": "¡Claro que sí!"}]$vn$::jsonb, $vn$YES$vn$, null, null, 35, $vn$Quick and warm, like you expected it. Do not dwell — the point is to move on having gained the credibility.$vn$, $vn$I already knew that name.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Más sobre Bolton$vn$), $vn$WHYES-003B$vn$, $vn$Slate — if no$vn$, $vn$Ya vas a escuchar de ellos. Son uno de los grupos de defensa financiera de más rápido crecimiento.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Ya vas a escuchar de ellos. Son uno de los grupos de defensa financiera de más rápido crecimiento."}]$vn$::jsonb, $vn$NO$vn$, null, null, 36, $vn$"You will" is the whole line — said with certainty it turns not knowing them into being early rather than being uninformed. Never make the client feel behind.$vn$, $vn$I am hearing about them before everyone else.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Más sobre Bolton$vn$), $vn$WHYES-004$vn$, $vn$What We Ask Of You$vn$, $vn$Lo único que te pedimos es que participes activamente con tu coach financiero certificado. Ellos harán todo el trabajo pesado por ti y en ## meses, tu deuda estará resuelta, tendrás buen crédito, ahorros en efectivo y un futuro financiero brillante. Bastante buen intercambio, ¿verdad?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Lo único que te pedimos es que participes activamente con tu coach financiero certificado. Ellos harán todo el trabajo pesado por ti y en ## meses, tu deuda estará resuelta, tendrás buen crédito, ahorros en efectivo y un futuro financiero brillante. Bastante buen intercambio, ¿verdad?"}]$vn$::jsonb, null, null, null, 40, $vn$Light on the ask, warm on the outcome. The word "tradeoff" should sound like an obvious bargain, not a negotiation.$vn$, $vn$Very little is being asked of me.$vn$, false, 'published');
